import { z } from "zod"

export type Product = { id: string; name: string; cents: number; note: string }

export const PRODUCTS: Product[] = [
  { id: "notebook", name: "Field notebook, A5 ruled", cents: 1400, note: "Stitched, 96 pages" },
  { id: "tape", name: "Washi tape, three rolls", cents: 900, note: "Dots, stripes, gingham" },
  { id: "pen", name: "Brass pen", cents: 2200, note: "Refillable, felt tip" },
]

export const DEFAULT_QTY = [1, 2, 1]

export const money = (cents: number): string => (cents / 100).toFixed(2)

export type MethodId = "standard" | "express" | "pickup"

export const METHODS: { id: MethodId; name: string; help: string; cents: number }[] = [
  { id: "standard", name: "Standard", help: "4 to 6 days. Free over 50.00.", cents: 490 },
  { id: "express", name: "Express", help: "Tomorrow, if you order before 4 pm.", cents: 990 },
  { id: "pickup", name: "Pick up at the shop", help: "12 rue de l'Eau, ready in an hour.", cents: 0 },
]

export const PROMOS: Record<string, { label: string; percent?: number; freeStandard?: boolean }> = {
  PAPER10: { label: "10% off the paper", percent: 10 },
  FREESHIP: { label: "Standard delivery on us", freeStandard: true },
}

export const FREE_SHIPPING_FROM = 5000
export const VAT = 23

export type Totals = { subtotal: number; discount: number; shipping: number; vat: number; total: number }

export function totals(qty: number[], method: MethodId, code: string | null): Totals {
  const subtotal = PRODUCTS.reduce((sum, p, i) => sum + p.cents * (qty[i] ?? 0), 0)
  const promo = code ? PROMOS[code] : undefined
  const discount = promo?.percent ? Math.round((subtotal * promo.percent) / 100) : 0
  const base = METHODS.find((m) => m.id === method)!.cents
  let shipping = base
  if (subtotal === 0) shipping = 0
  else if (method === "standard" && (subtotal - discount >= FREE_SHIPPING_FROM || promo?.freeStandard)) shipping = 0
  else if (method === "express" && promo?.freeStandard) shipping = base - METHODS[0]!.cents
  const total = subtotal - discount + shipping
  return { subtotal, discount, shipping, vat: Math.round((total * VAT) / (100 + VAT)), total }
}

export function luhn(digits: string): boolean {
  let sum = 0
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i])
    if (i % 2 === 1) {
      d *= 2
      if (d > 9) d -= 9
    }
    sum += d
  }
  return digits.length > 0 && sum % 10 === 0
}

export function formatCardNumber(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 19)
  if (/^3[47]/.test(d)) return [d.slice(0, 4), d.slice(4, 10), d.slice(10, 15)].filter(Boolean).join(" ")
  return d.replace(/(.{4})/g, "$1 ").trim()
}

export function formatExpiry(raw: string): string {
  const d = raw.replace(/\D/g, "").slice(0, 4)
  if (d.length === 1 && Number(d) > 1) return `0${d}/`
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

export type Month = { year: number; month: number }

export function currentMonth(): Month {
  // lint-house-disable-next-line render-time
  const now = new Date()
  return { year: now.getFullYear(), month: now.getMonth() + 1 }
}

export const COUNTRIES = ["Portugal", "France", "Germany", "Netherlands", "United Kingdom", "United States"]

export function makeCheckoutSchema(today: Month) {
  return z
    .object({
      email: z.email("Enter an address like ada@notes.dev."),
      name: z.string().trim().min(2, "Who should we address it to?"),
      address: z.string().trim(),
      city: z.string().trim(),
      postcode: z.string().trim(),
      country: z.string().min(1, "Choose a country."),
      method: z.enum(["standard", "express", "pickup"]),
      cardName: z.string().trim().min(2, "Type the name as it is printed on the card."),
      cardNumber: z
        .string()
        .refine((v) => /^\d{13,19}$/.test(v.replace(/\s/g, "")), "A card number has 13 to 19 digits.")
        .refine((v) => luhn(v.replace(/\s/g, "")), "That number does not add up. Check each digit."),
      expiry: z
        .string()
        .regex(/^(0[1-9]|1[0-2])\/\d{2}$/, "Write it as MM/YY, like 08/28.")
        .refine((v) => {
          const [m, y] = v.split("/").map(Number)
          return 2000 + y > today.year || (2000 + y === today.year && m >= today.month)
        }, "That card has expired."),
      cvc: z.string().regex(/^\d{3,4}$/, "The security code is 3 or 4 digits."),
      terms: z.boolean().refine((v) => v, "Please tick the box to place the order."),
    })
    .superRefine((v, ctx) => {
      if (v.method === "pickup") return
      if (v.address.length < 5) ctx.addIssue({ code: "custom", path: ["address"], message: "Where should it go? Add a street and number." })
      if (v.city.length < 2) ctx.addIssue({ code: "custom", path: ["city"], message: "Add the town or city." })
      if (v.postcode.length < 3) ctx.addIssue({ code: "custom", path: ["postcode"], message: "Add the postal code." })
    })
}

export type CheckoutValues = z.infer<ReturnType<typeof makeCheckoutSchema>>

export const DEFAULT_VALUES: CheckoutValues = {
  email: "",
  name: "",
  address: "",
  city: "",
  postcode: "",
  country: "Portugal",
  method: "standard",
  cardName: "",
  cardNumber: "",
  expiry: "",
  cvc: "",
  terms: false,
}

export const FIELD_LABELS: Partial<Record<keyof CheckoutValues, string>> = {
  email: "Email",
  name: "Full name",
  address: "Street and number",
  city: "Town or city",
  postcode: "Postal code",
  country: "Country",
  cardName: "Name on card",
  cardNumber: "Card number",
  expiry: "Expires",
  cvc: "Security code",
  terms: "The terms",
}

"use client"

import * as React from "react"
import { zodResolver } from "@hookform/resolvers/zod"
import { useForm } from "react-hook-form"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Mascot } from "@/components/ui/mascot"
import { Page, PageDescription, PageHeader, PageTitle } from "@/components/ui/page"
import { Receipt, ReceiptFooter, ReceiptHeader, ReceiptLine, ReceiptLines, ReceiptTotal } from "@/components/ui/receipt"
import { Stamp } from "@/components/ui/stamp"
import { Checkout01Form } from "@/components/blocks/checkout-01/components/checkout-01-form"
import { Checkout01Summary } from "@/components/blocks/checkout-01/components/checkout-01-summary"
import {
  DEFAULT_QTY,
  DEFAULT_VALUES,
  METHODS,
  PRODUCTS,
  currentMonth,
  makeCheckoutSchema,
  money,
  totals as totalsOf,
  type CheckoutValues,
  type Month,
  type MethodId,
  type Totals,
} from "@/components/blocks/checkout-01/components/checkout-01-data"
import { cn } from "@/lib/utils"

export type PlacedOrder = { number: string; email: string; name: string; qty: number[]; totals: Totals; code: string | null }

type Props = {
  className?: string
  defaultQty?: number[]
  orderNumber?: string
  today?: Month
  onPlace?: (order: PlacedOrder, values: CheckoutValues) => void | Promise<void>
}

export default function Checkout01({ className, defaultQty = DEFAULT_QTY, orderNumber = "0042 1187", today, onPlace }: Props) {
  const formId = React.useId()
  const [qty, setQty] = React.useState<number[]>(defaultQty)
  const [code, setCode] = React.useState<string | null>(null)
  const [placing, setPlacing] = React.useState(false)
  const [placed, setPlaced] = React.useState<PlacedOrder | null>(null)
  const [failure, setFailure] = React.useState("")
  const done = React.useRef<HTMLHeadingElement>(null)

  const form = useForm<CheckoutValues>({
    resolver: (values, context, options) => zodResolver(makeCheckoutSchema(today ?? currentMonth()))(values, context, options),
    defaultValues: DEFAULT_VALUES,
    mode: "onTouched",
  })
  const method = form.watch("method") as MethodId
  const totals = totalsOf(qty, method, code)
  const shipping = Object.fromEntries(METHODS.map((m) => [m.id, totalsOf(qty, m.id, code).shipping])) as Record<MethodId, number>

  React.useEffect(() => {
    if (placed) done.current?.focus()
  }, [placed])

  const submit = form.handleSubmit(async (values) => {
    const order: PlacedOrder = { number: orderNumber, email: values.email, name: values.name, qty, totals, code }
    setPlacing(true)
    setFailure("")
    try {
      await onPlace?.(order, values)
      setPlaced(order)
    } catch (err) {
      setFailure(err instanceof Error && err.message ? err.message : "Something went wrong on our side.")
    } finally {
      setPlacing(false)
    }
  })

  if (placed) {
    return (
      <section aria-labelledby={`${formId}-done`} className={cn("mx-auto grid w-full max-w-3xl justify-items-center gap-6 px-4 py-12 text-center sm:px-8", className)}>
        <Mascot pose="celebrate" size={132} seed="checkout-done" />
        <div className="grid gap-2">
          <h2 id={`${formId}-done`} ref={done} tabIndex={-1} className="font-script text-5xl leading-none font-bold outline-none">
            Thank you, {placed.name.trim().split(/\s+/)[0]}
          </h2>
          <p className="text-lg text-muted-foreground">
            Order <span className="ll-num font-bold text-foreground">{placed.number}</span> is paid. The receipt is on its way to {placed.email}.
          </p>
        </div>
        <div className="relative">
          <Receipt as="article" seed="checkout-paid" aria-label="Receipt of your order">
            <ReceiptHeader>
              <span>Looseleaf shop</span>
              <span>Order {placed.number}</span>
            </ReceiptHeader>
            <ReceiptLines>
              {PRODUCTS.map((p, i) =>
                placed.qty[i] ? (
                  <ReceiptLine key={p.id} qty={placed.qty[i]} price={money(p.cents * placed.qty[i]!)}>
                    {p.name}
                  </ReceiptLine>
                ) : null
              )}
            </ReceiptLines>
            <ReceiptTotal circled>{money(placed.totals.total)}</ReceiptTotal>
            <ReceiptFooter>paid by card - thank you</ReceiptFooter>
          </Receipt>
          <Stamp name="stamp-paid" className="absolute -end-6 -top-4 sm:-end-12" seed="paid" />
        </div>
        <Button
          variant="outline"
          onClick={() => {
            setPlaced(null)
            setQty(defaultQty)
            setCode(null)
            form.reset()
          }}
        >
          Keep shopping
        </Button>
      </section>
    )
  }

  return (
    <div className={cn("@container/checkout mx-auto w-full max-w-6xl px-4 py-10 sm:px-8", className)}>
      <div className="grid items-start gap-10 @4xl/checkout:grid-cols-[minmax(0,1fr)_24rem]">
        <Page as="section" width="full" tape="top" seed="checkout-form" aria-labelledby={`${formId}-title`}>
          <PageHeader>
            <PageTitle as="h2" id={`${formId}-title`} underline="wavy" seed="checkout-title">
              Checkout
            </PageTitle>
            <PageDescription>Three short steps and it is on its way. We ask for nothing we do not need.</PageDescription>
          </PageHeader>
          {failure ? (
            <Alert variant="destructive">
              <Icon name="circle-alert" />
              <AlertTitle>The order was not placed</AlertTitle>
              <AlertDescription>{failure} You have not been charged. Try again, or use another card.</AlertDescription>
            </Alert>
          ) : null}
          <Checkout01Form form={form} id={formId} onSubmit={submit} shipping={shipping} />
        </Page>
        <div className="@4xl/checkout:sticky @4xl/checkout:top-6">
          <Checkout01Summary
            qty={qty}
            onQty={(i, v) => setQty((all) => all.map((n, k) => (k === i ? v : n)))}
            code={code}
            onCode={setCode}
            totals={totals}
            formId={formId}
            orderNumber={orderNumber}
            placing={placing}
          />
        </div>
      </div>
    </div>
  )
}
